// The mbstring extension: text written in some encoding other than the
// run's own, and the bringing of one such over into another. Written in
// PHP because it is PHP's and not the kernel's.
// Hand-written; scripts/port_examples.py leaves native/ alone.
//
// Text here is held as the bytes it was written in, so a character of a
// piece of text stands for one byte and no more. An encoding is
// therefore a mapping of one run of bytes onto another, and everything
// below reads and writes bytes: nothing here asks the run to read a
// byte as a letter, because under this definition it never does.

// The encodings this run knows, each answering to the name the
// reference gives it. A name is looked for without regard to case or
// to the marks between its pieces, so that utf8, UTF-8 and Utf_8 are
// one name.
function __mb_encoding_named($said) {
    if (!is_string($said)) { return false; }
    $plain = "";
    $at = 0;
    while ($at < strlen($said)) {
        $letter = $said[$at];
        if ($letter !== "-" && $letter !== "_" && $letter !== " ") { $plain = $plain . $letter; }
        $at = $at + 1;
    }
    $plain = strtolower($plain);
    if ($plain === "utf8") { return "UTF-8"; }
    if ($plain === "sjis" || $plain === "shiftjis" || $plain === "xsjis" || $plain === "csshiftjis") { return "SJIS"; }
    if ($plain === "ascii" || $plain === "usascii" || $plain === "iso646us") { return "ASCII"; }
    if ($plain === "iso88591" || $plain === "latin1" || $plain === "csisolatin1") { return "ISO-8859-1"; }
    if ($plain === "8bit" || $plain === "binary") { return "8bit"; }
    return false;
}

// Shift_JIS, byte pair for byte pair. Each row below is what one lead
// byte makes of the byte that follows it: the numbers of the characters
// in four figures of sixteen apiece, from the trail byte 0x40 upward
// with 0x7f passed over, and nought where the pair spells nothing. The
// rows are what the reference implementation answers, pair for pair.
$__mb_sjis_rows = null;
function __mb_sjis_rows() {
    global $__mb_sjis_rows;
    if ($__mb_sjis_rows === null) {
        $__mb_sjis_rows = array(
            0x81 => "",
            0x82 => "",
            0x83 => "",
            0x84 => "",
            0x88 => "",
            0x89 => "",
            0x8a => "",
            0x8b => "",
            0x8c => "",
            0x8d => "",
            0x8e => "",
            0x8f => "",
            0x90 => "",
            0x91 => "",
            0x92 => "",
            0x93 => "",
            0x94 => "",
            0x95 => "",
            0x96 => "",
            0x97 => "",
            0x98 => "",
            0x99 => "",
            0x9a => "",
            0x9b => "",
            0x9c => "",
            0x9d => "",
            0x9e => "",
            0x9f => "",
            0xe0 => "",
            0xe1 => "",
            0xe2 => "",
            0xe3 => "",
            0xe4 => "",
            0xe5 => "",
            0xe6 => "",
            0xe7 => "",
            0xe8 => "",
            0xe9 => "",
            0xea => "",
        );
    }
    return $__mb_sjis_rows;
}

// Where in a row the byte after a lead byte stands. The byte 0x7f is no
// trail byte, so the places above it are one less than the byte says.
function __mb_sjis_place($trail) {
    if ($trail < 0x40 || $trail > 0xfc || $trail === 0x7f) { return -1; }
    if ($trail < 0x7f) { return $trail - 0x40; }
    return $trail - 0x41;
}

// The number of the character a pair of bytes spells, or nought where
// the pair spells none.
function __mb_sjis_code($lead, $trail) {
    $place = __mb_sjis_place($trail);
    if ($place < 0) { return 0; }
    $rows = __mb_sjis_rows();
    if (!array_key_exists($lead, $rows)) { return 0; }
    $row = $rows[$lead];
    if (($place + 1) * 4 > strlen($row)) { return 0; }
    return hexdec(substr($row, $place * 4, 4));
}

// The same table read the other way about: every character the encoding
// has, under its number, against the bytes that spell it. It is worked
// out from the rows the first time it is wanted and no sooner, since a
// program that never writes Shift_JIS has no use for it. The nine at
// the end are characters the encoding does not itself carry that the
// reference nonetheless writes as the nearest it has.
$__mb_sjis_backward = null;
function __mb_sjis_backward() {
    global $__mb_sjis_backward;
    if ($__mb_sjis_backward === null) {
        $held = array();
        $at = 0;
        while ($at < 0x80) { $held[$at] = chr($at); $at = $at + 1; }
        $at = 0;
        while ($at < 63) { $held[0xff61 + $at] = chr(0xa1 + $at); $at = $at + 1; }
        foreach (__mb_sjis_rows() as $lead => $row) {
            $place = 0;
            $places = strlen($row) / 4;
            while ($place < $places) {
                $code = hexdec(substr($row, $place * 4, 4));
                if ($code !== 0) {
                    $trail = $place < 63 ? 0x40 + $place : 0x41 + $place;
                    $held[$code] = chr($lead) . chr($trail);
                }
                $place = $place + 1;
            }
        }
        $near = array(0xa5 => 0x818f, 0xaf => 0x8150, 0x203e => 0x8150, 0x2225 => 0x8161, 0xff0d => 0x817c,
                      0xff5e => 0x8160, 0xffe0 => 0x8191, 0xffe1 => 0x8192, 0xffe2 => 0x81ca);
        foreach ($near as $code => $pair) { $held[$code] = chr($pair >> 8) . chr($pair & 0xff); }
        $__mb_sjis_backward = $held;
    }
    return $__mb_sjis_backward;
}

// A character's number written as the bytes UTF-8 spells it with.
function __mb_utf8_of($code) {
    if ($code < 0x80) { return chr($code); }
    if ($code < 0x800) { return chr(0xc0 + ($code >> 6)) . chr(0x80 + ($code & 0x3f)); }
    if ($code < 0x10000) {
        return chr(0xe0 + ($code >> 12)) . chr(0x80 + (($code >> 6) & 0x3f)) . chr(0x80 + ($code & 0x3f));
    }
    return chr(0xf0 + ($code >> 18)) . chr(0x80 + (($code >> 12) & 0x3f)) . chr(0x80 + (($code >> 6) & 0x3f))
         . chr(0x80 + ($code & 0x3f));
}

// One character of UTF-8 read at a place: its number and how many bytes
// it took. A number below nought says the bytes there spell no
// character, which covers a byte that begins nothing, a run cut short,
// a number written wider than it needed to be, half of a pair that
// names no character of its own, and a number past the last there is.
function __mb_utf8_step($text, $at) {
    $end = strlen($text);
    $byte = ord($text[$at]);
    if ($byte < 0x80) { return array($byte, 1); }
    if ($byte < 0xc2 || $byte > 0xf4) { return array(-1, 1); }
    $wide = $byte < 0xe0 ? 2 : ($byte < 0xf0 ? 3 : 4);
    if ($at + $wide > $end) { return array(-1, 1); }
    $second = ord($text[$at + 1]);
    if ($byte === 0xe0 && $second < 0xa0) { return array(-1, 1); }
    if ($byte === 0xed && $second > 0x9f) { return array(-1, 1); }
    if ($byte === 0xf0 && $second < 0x90) { return array(-1, 1); }
    if ($byte === 0xf4 && $second > 0x8f) { return array(-1, 1); }
    $code = $byte & (0x7f >> $wide);
    $step = 1;
    while ($step < $wide) {
        $next = ord($text[$at + $step]);
        if ($next < 0x80 || $next > 0xbf) { return array(-1, 1); }
        $code = $code * 64 + ($next & 0x3f);
        $step = $step + 1;
    }
    return array($code, $wide);
}

// The same for Shift_JIS. A byte below 0x80 stands for itself, one from
// 0xa1 to 0xdf is a half-width kana, and one in the two lead ranges
// takes the byte after it with it whether or not the two spell
// anything. Every other byte spells nothing on its own.
function __mb_sjis_step($text, $at) {
    $byte = ord($text[$at]);
    if ($byte < 0x80) { return array($byte, 1); }
    if ($byte >= 0xa1 && $byte <= 0xdf) { return array(0xff61 + $byte - 0xa1, 1); }
    if (($byte >= 0x81 && $byte <= 0x9f) || ($byte >= 0xe0 && $byte <= 0xef)) {
        if ($at + 1 >= strlen($text)) { return array(-1, 1); }
        $code = __mb_sjis_code($byte, ord($text[$at + 1]));
        return array($code === 0 ? -1 : $code, 2);
    }
    return array(-1, 1);
}

// One character of a piece of text read at a place, in the encoding
// named: its number and how many bytes it took, with a number below
// nought where the bytes there spell nothing.
function __mb_step($text, $at, $encoding) {
    if ($encoding === "UTF-8") { return __mb_utf8_step($text, $at); }
    if ($encoding === "SJIS") { return __mb_sjis_step($text, $at); }
    if ($encoding === "ASCII") {
        $byte = ord($text[$at]);
        return array($byte < 0x80 ? $byte : -1, 1);
    }
    return array(ord($text[$at]), 1);
}

// A character's number written in the encoding named, or false where
// the encoding has no character of that number.
function __mb_letter_of($code, $encoding) {
    if ($encoding === "UTF-8") { return __mb_utf8_of($code); }
    if ($encoding === "ASCII") { return $code < 0x80 ? chr($code) : false; }
    if ($encoding === "ISO-8859-1" || $encoding === "8bit") { return $code < 0x100 ? chr($code) : false; }
    $backward = __mb_sjis_backward();
    if (!array_key_exists($code, $backward)) { return false; }
    return $backward[$code];
}

// What stands in a piece of text for a character the encoding written
// to has none of, and for bytes that spell nothing in the encoding read
// from. The reference calls this the substitute character.
function __mb_stand_in() { return "?"; }

// How far into a piece of text the encoding named reads before meeting
// bytes that spell nothing in it. The whole length means the text is
// written in that encoding throughout.
function __mb_read_as_far($text, $encoding) {
    $at = 0;
    $end = strlen($text);
    while ($at < $end) {
        $step = __mb_step($text, $at, $encoding);
        if ($step[0] < 0) { return $at; }
        $at = $at + $step[1];
    }
    return $end;
}

// The encoding a run holds its own text in: what the settings say, and
// UTF-8 where they say nothing.
function __mb_internal() {
    $said = ini_get("internal_encoding");
    if ($said === false || $said === "") { $said = ini_get("default_charset"); }
    if ($said === false || $said === "") { $said = "UTF-8"; }
    $named = __mb_encoding_named($said);
    return $named === false ? "UTF-8" : $named;
}

// The encodings a piece of text is to be tried against, where none were
// named: the order the reference looks in.
function __mb_detect_order($said) {
    if ($said === null || $said === "") { return array("ASCII", "UTF-8"); }
    if (is_array($said)) { $names = $said; }
    else { $names = explode(",", $said); }
    $order = array();
    foreach ($names as $name) {
        $named = __mb_encoding_named(trim((string) $name));
        if ($named !== false) { $order[] = $named; }
    }
    if (count($order) === 0) { return array("ASCII", "UTF-8"); }
    return $order;
}

// The encoding a name stands for, where it stands for one. A name that
// answers to no encoding this run knows stops the run, which is what
// the reference does with it.
function __mb_must_be_encoding($said, $which, $called) {
    $named = __mb_encoding_named($said);
    if ($named === false) {
        throw new ValueError($called . '(): Argument #' . $which . ' must be a valid encoding, "' . (string) $said . '" given');
    }
    return $named;
}

// A piece of text written again in another encoding, character for
// character. A character the encoding written to has none of, and bytes
// that spell nothing in the encoding read from, both come out as the
// substitute character.
function mb_convert_encoding($string, $to_encoding, $from_encoding = null) {
    $to = __mb_must_be_encoding($to_encoding, '2 ($to_encoding)', 'mb_convert_encoding');
    if (is_array($string)) {
        $done = array();
        foreach ($string as $key => $worth) { $done[$key] = mb_convert_encoding($worth, $to_encoding, $from_encoding); }
        return $done;
    }
    $string = (string) $string;
    if ($from_encoding === null) { $from = __mb_internal(); }
    elseif (is_array($from_encoding) || strpos((string) $from_encoding, ",") !== false) {
        $from = mb_detect_encoding($string, $from_encoding, false);
        if ($from === false) { $from = __mb_internal(); }
    }
    else { $from = __mb_must_be_encoding($from_encoding, '3 ($from_encoding)', 'mb_convert_encoding'); }
    if ($from === $to) { return $string; }
    $out = "";
    $at = 0;
    $end = strlen($string);
    while ($at < $end) {
        $step = __mb_step($string, $at, $from);
        if ($step[0] < 0) { $out = $out . __mb_stand_in(); }
        else {
            $written = __mb_letter_of($step[0], $to);
            $out = $out . ($written === false ? __mb_stand_in() : $written);
        }
        $at = $at + $step[1];
    }
    return $out;
}

// How many characters a piece of text holds in the encoding named.
// Bytes that spell nothing count as one character apiece, since the
// reference stands a substitute character in their place.
function mb_strlen($string, $encoding = null) {
    $held = $encoding === null ? __mb_internal() : __mb_must_be_encoding($encoding, '2 ($encoding)', 'mb_strlen');
    $string = (string) $string;
    $count = 0;
    $at = 0;
    $end = strlen($string);
    while ($at < $end) {
        $step = __mb_step($string, $at, $held);
        $at = $at + $step[1];
        $count = $count + 1;
    }
    return $count;
}

// The characters of a piece of text, one to a place, each as the bytes
// that spell it. Bytes that spell nothing come back as the substitute
// character, one for each character they were read as, which is how the
// reference hands back a piece of a text it could not wholly read.
function __mb_letters($string, $encoding) {
    $letters = array();
    $at = 0;
    $end = strlen($string);
    while ($at < $end) {
        $step = __mb_step($string, $at, $encoding);
        $letters[] = $step[0] < 0 ? __mb_stand_in() : substr($string, $at, $step[1]);
        $at = $at + $step[1];
    }
    return $letters;
}

// A run of characters out of a piece of text, counted in characters and
// not in bytes. A start below nought counts back from the end, and so
// does a length below nought, which then says how many characters to
// leave at the end rather than how many to take.
function mb_substr($string, $start, $length = null, $encoding = null) {
    $held = $encoding === null ? __mb_internal() : __mb_must_be_encoding($encoding, '4 ($encoding)', 'mb_substr');
    $letters = __mb_letters((string) $string, $held);
    $count = count($letters);
    $from = whole_of($start);
    if ($from < 0) { $from = $count + $from; }
    if ($from < 0) { $from = 0; }
    if ($from > $count) { $from = $count; }
    if ($length === null) { $to = $count; }
    else {
        $wanted = whole_of($length);
        $to = $wanted < 0 ? $count + $wanted : $from + $wanted;
    }
    if ($to < $from) { $to = $from; }
    if ($to > $count) { $to = $count; }
    $out = "";
    while ($from < $to) {
        $out = $out . $letters[$from];
        $from = $from + 1;
    }
    return $out;
}

// The encoding the run holds its own text in, and the setting of it.
function mb_internal_encoding($encoding = null) {
    if ($encoding === null) { return __mb_internal(); }
    $named = __mb_encoding_named($encoding);
    if ($named === false) {
        throw new ValueError('mb_internal_encoding(): Argument #1 ($encoding) must be a valid encoding, "' . (string) $encoding . '" given');
    }
    ini_set("internal_encoding", $named);
    return true;
}

// Which of the encodings named a piece of text is likeliest written in.
// Asked strictly, the answer is the first that reads the whole of the
// text and false where none does; asked otherwise, it is the one that
// reads furthest before meeting anything it cannot, the earliest named
// of those where two read equally far. The reference weighs besides how
// likely the characters that come out are, so where a text reads whole
// in more than one of the encodings named the two may not agree.
function mb_detect_encoding($string, $encodings = null, $strict = false) {
    $order = __mb_detect_order($encodings);
    $string = (string) $string;
    $best = false;
    $furthest = -1;
    foreach ($order as $named) {
        $read = __mb_read_as_far($string, $named);
        if ($read === strlen($string)) { return $named; }
        if ($read > $furthest) { $furthest = $read; $best = $named; }
    }
    if ($strict) { return false; }
    return $best;
}

// Whether a piece of text is written throughout in the encoding named.
// A list is answered for only where every piece of it is, and nothing
// given at all asks after everything the request carried.
function mb_check_encoding($value = null, $encoding = null) {
    $held = $encoding === null ? __mb_internal() : __mb_must_be_encoding($encoding, '2 ($encoding)', 'mb_check_encoding');
    if ($value === null) { return true; }
    if (is_array($value)) {
        foreach ($value as $key => $worth) {
            if (is_string($key) && !mb_check_encoding($key, $held)) { return false; }
            if (!mb_check_encoding($worth, $held)) { return false; }
        }
        return true;
    }
    $value = (string) $value;
    return __mb_read_as_far($value, $held) === strlen($value);
}

// ------------------------------------------------------------------
// The request, brought over into the run's own encoding.
//
// Where a run is told to translate what comes in, everything a query, a
// form or a crumb carries is read in the encoding the request was
// written in and written again in the run's own before the program sees
// any of it — the names as much as the worths. The settings are read
// as the run was started with them, since nothing of the program has
// run yet to have written any of them.

function __mb_setting_said($name) {
    global $__started_with;
    if (!is_array($__started_with)) { return ""; }
    if (!array_key_exists($name, $__started_with)) { return ""; }
    return (string) $__started_with[$name];
}

function __mb_setting_encoding($name) {
    $said = __mb_setting_said($name);
    if ($said === "") { $said = __mb_setting_said("default_charset"); }
    if ($said === "") { $said = "UTF-8"; }
    return __mb_encoding_named($said);
}

// The two encodings a request is to be brought over between, or nothing
// where the run was not told to bring it over at all.
function __mb_request_encodings() {
    $said = strtolower(trim(__mb_setting_said("mbstring.encoding_translation")));
    if ($said === "" || $said === "0" || $said === "off" || $said === "false") { return null; }
    $from = __mb_setting_encoding("input_encoding");
    $to = __mb_setting_encoding("internal_encoding");
    if ($from === false || $to === false || $from === $to) { return null; }
    return array($from, $to);
}

// Everything a group of the request carries, written again in another
// encoding: the names of the places as much as what stands in them.
function __mb_carried_over($held, $from, $to) {
    if (is_array($held)) {
        $done = array();
        foreach ($held as $key => $worth) {
            $named = is_string($key) ? mb_convert_encoding($key, $to, $from) : $key;
            $done[$named] = __mb_carried_over($worth, $from, $to);
        }
        return $done;
    }
    if (is_string($held)) { return mb_convert_encoding($held, $to, $from); }
    return $held;
}

// A piece of text cut at a mark of one byte, where the mark is only a
// mark when it stands whole and not within a character. Under an
// encoding whose characters may end in a byte that is a mark elsewhere,
// this is the difference between reading a name and mangling it.
function __mb_cut($text, $mark, $encoding) {
    $pieces = array();
    $held = "";
    $at = 0;
    $end = strlen($text);
    while ($at < $end) {
        $step = __mb_step($text, $at, $encoding);
        $wide = $step[1];
        $piece = substr($text, $at, $wide);
        if ($wide === 1 && $piece === $mark) { $pieces[] = $held; $held = ""; }
        else { $held = $held . $piece; }
        $at = $at + $wide;
    }
    $pieces[] = $held;
    return $pieces;
}

// What a head line of a part says after the equals mark, read a
// character at a time so that a byte standing within a character is
// never taken for a mark. Given between quotes, a backslash before the
// closing quote or before another backslash is that character itself —
// but only where the backslash is a character and not the tail of one.
function __mb_unquoted($text, $encoding) {
    $text = ltrim($text);
    $closing = "";
    $at = 0;
    if ($text !== "" && ($text[0] === '"' || $text[0] === "'")) { $closing = $text[0]; $at = 1; }
    $out = "";
    $end = strlen($text);
    while ($at < $end) {
        $step = __mb_step($text, $at, $encoding);
        $wide = $step[1];
        $piece = substr($text, $at, $wide);
        if ($wide === 1) {
            if ($closing !== "" && $piece === $closing) { return $out; }
            if ($closing === "" && ($piece === " " || $piece === "\t")) { return $out; }
            if ($piece === "\\" && $at + 1 < $end) {
                $next = $text[$at + 1];
                if ($next === "\\" || ($closing !== "" && $next === $closing)) {
                    $out = $out . $next;
                    $at = $at + 2;
                    continue;
                }
            }
        }
        $out = $out . $piece;
        $at = $at + $wide;
    }
    return $out;
}

// What a part's head calls something, read in the encoding named.
function __mb_head_says($head, $what, $encoding) {
    foreach (explode("\n", $head) as $line) {
        $line = rtrim($line, "\r");
        $pieces = __mb_cut($line, ";", $encoding);
        $count = count($pieces);
        $which = 1;
        while ($which < $count) {
            $piece = ltrim($pieces[$which]);
            $which = $which + 1;
            if (substr($piece, 0, strlen($what)) !== $what) { continue; }
            $rest = ltrim(substr($piece, strlen($what)));
            if ($rest === "" || $rest[0] !== "=") { continue; }
            return __mb_unquoted(substr($rest, 1), $encoding);
        }
    }
    return null;
}

// The first step of a name that points inside a value: what stands
// before the first bracket, with a dot or a space in it made an
// underscore, which is how a form's names have always been taken.
function __mb_first_step($name) {
    $at = strpos($name, "[");
    $head = $at === false ? $name : substr($name, 0, $at);
    return str_replace(array(".", " "), "_", $head);
}

// The last piece of what a part called its file: a browser handing over
// a whole directory names each file by its way in, and only the last
// step of that is the file's own name.
function __mb_last_step($path, $encoding) {
    $pieces = __mb_cut($path, "/", $encoding);
    $last = $pieces[count($pieces) - 1];
    $pieces = __mb_cut($last, "\\", $encoding);
    return $pieces[count($pieces) - 1];
}

// The parts of a body written in parts, each read twice: once byte for
// byte, as the host read it, and once in the encoding the request came
// in. The two differ where a character of a name ends in the byte the
// escape mark is written with, which the host, reading bytes, took for
// an escape. Each part gives the name the host made of it, the name
// that was truly sent, and the same again for the file it named.
function __mb_parts_of($body, $boundary, $encoding) {
    $found = array();
    $mark = "--" . $boundary;
    $at = strpos($body, $mark);
    while ($at !== false) {
        $at = $at + strlen($mark);
        if (substr($body, $at, 2) === "--") { break; }
        $shut = strpos($body, "\r\n\r\n", $at);
        $gap = 4;
        $other = strpos($body, "\n\n", $at);
        if ($shut === false || ($other !== false && $other < $shut)) { $shut = $other; $gap = 2; }
        if ($shut === false) { break; }
        $head = substr($body, $at, $shut - $at);
        $found[] = array(__mb_head_says($head, "name", "8bit"), __mb_head_says($head, "name", $encoding),
